#include <bits/stdc++.h>
using namespace std;

class Solution {public:int largestVariance(string s){int ans=0;vector<int> cnt(26);for(char c:s)++cnt[c-'a'];for(int a=0;a<26;++a)for(int b=0;b<26;++b){if(a==b||!cnt[a]||!cnt[b])continue;int ca=0,cb=0,remaining=cnt[b];for(char ch:s){int x=ch-'a';if(x!=a&&x!=b)continue;if(x==a)++ca;else{++cb;--remaining;}if(cb)ans=max(ans,ca-cb);if(ca<cb&&remaining>0)ca=cb=0;}}return ans;} };
